static void strip_params_colon(char *const params) /* <=== strip_params_colon */ 
{
	char *s;

	if (params == NULL) {
		return;
	}

	s = params;
	while (*s != '\0') {
		if (*s == ':') {
			memmove(s, s+1, strlen(s+1)+1);
			return;
		}

		s = strchr(s, ' ');
		if (s == NULL) {
			return;
		}

		while (*s == ' ') {
			s++;
		}
	}
}

int signal_emit(const char *signal, int params, ...) /* <=== signal_emit */ 
{
	Signal *rec;
	va_list va;
	int signal_id;

	g_return_val_if_fail(params >= 0 && params <= SIGNAL_MAX_ARGUMENTS, FALSE);

	signal_id = signal_get_uniq_id(signal);

	rec = g_hash_table_lookup(signals, GINT_TO_POINTER(signal_id));
	if (rec != NULL) {
		va_start(va, params);
		signal_emit_real(rec, params, va, rec->hooks);
		va_end(va);
	}

	return rec != NULL;
}

char *event_get_params(const char *data, int count, ...) /* <=== event_get_params */ 
{
	char **str, *tmp, *duprec, *datad;
	gboolean rest;
	va_list args;

	g_return_val_if_fail(data != NULL, NULL);

	va_start(args, count);
	duprec = datad = g_strdup(data);

	rest = count & PARAM_FLAG_GETREST;
	count = PARAM_WITHOUT_FLAGS(count);

	while (count-- > 0) {
		str = (char **) va_arg(args, char **);
		if (count == 0 && rest) {
			/* Put the rest into the last parameter. */
			strip_params_colon(datad);
			tmp = datad;
		} else {
			tmp = event_get_param(&datad);
		}
		if (str != NULL) *str = tmp;
	}
	va_end(args);

	return duprec;
}

void irc_send_cmd_now(IRC_SERVER_REC *server, const char *cmd) /* <=== irc_send_cmd_now */ 
{
	g_return_if_fail(cmd != NULL);

        irc_send_cmd_full(server, cmd, TRUE, TRUE, FALSE);
}

void irc_servers_start_cmd_timeout(void) /* <=== irc_servers_start_cmd_timeout */ 
{
	if (cmd_tag == -1)
		cmd_tag = g_timeout_add(500, (GSourceFunc) servers_cmd_timeout, NULL);
}

void irc_send_cmd_full(IRC_SERVER_REC *server, const char *cmd, /* <=== irc_send_cmd_full */ 
		       int send_now, int immediate, int raw)
{
	GString *str;
	int len;
	gboolean server_supports_tag;

	g_return_if_fail(server != NULL);
	g_return_if_fail(cmd != NULL);

	if (server->connection_lost)
		return;

	str = g_string_sized_new(MAX_IRC_USER_TAGS_LEN + 2 /* `@'+SPACE */ +
				 server->max_message_len + 2 /* CR+LF */ + 1 /* `\0' */);

	if (server->cmdcount == 0)
		irc_servers_start_cmd_timeout();
	server->cmdcount++;

	if (!raw) {
		const char *tmp = cmd;

		server_supports_tag = server->cap_supported != NULL &&
			g_hash_table_lookup_extended(server->cap_supported, CAP_MESSAGE_TAGS, NULL, NULL);

		if (*cmd == '@' && server_supports_tag) {
			const char *end;

			while (*tmp != ' ' && *tmp != '\0')
				tmp++;

			end = tmp;

			if (tmp - cmd > MAX_IRC_USER_TAGS_LEN) {
				g_warning("irc_send_cmd_full(); tags too long(%ld)", tmp - cmd);
				while (tmp - cmd > MAX_IRC_USER_TAGS_LEN && cmd != tmp - 1) tmp--;
				while (*tmp != ',' && cmd != tmp - 1) tmp--;
			}
			if (cmd != tmp)
				g_string_append_len(str, cmd, tmp - cmd);

			tmp = end;
			while (*tmp == ' ') tmp++;

			if (*tmp != '\0' && str->len > 0)
				g_string_append_c(str, ' ');
		}
		len = strlen(tmp);

		/* check that we don't send any longer commands
		   than 510 bytes (2 bytes for CR+LF) */
		g_string_append_len(str, tmp, len > server->max_message_len ?
				    server->max_message_len : len);
	} else {
		g_string_append(str, cmd);
	}

	if (send_now) {
		rawlog_output(server->rawlog, str->str);
		server_redirect_command(server, str->str, server->redirect_next);
                server->redirect_next = NULL;
	}

	if (!raw) {
                /* Add CR+LF to command */
		g_string_append_c(str, 13);
		g_string_append_c(str, 10);
	}

	if (send_now) {
                irc_server_send_data(server, str->str, str->len);
		g_string_free(str, TRUE);
	} else {

		/* add to queue */
		if (immediate) {
			server->cmdqueue = g_slist_prepend(server->cmdqueue,
							   server->redirect_next);
			server->cmdqueue = g_slist_prepend(server->cmdqueue,
							   g_string_free(str, FALSE));
		} else {
			server->cmdqueue = g_slist_append(server->cmdqueue,
							  g_string_free(str, FALSE));
			server->cmdqueue = g_slist_append(server->cmdqueue,
							  server->redirect_next);
		}
	}
        server->redirect_next = NULL;
}

char *event_get_param(char **data) /* <=== event_get_param */ 
{
	char *pos;

	g_return_val_if_fail(data != NULL, NULL);
	g_return_val_if_fail(*data != NULL, NULL);

	if (**data == ':') {
		/* last parameter */
		pos = *data;
		*data += strlen(*data);
		return pos+1;
	}

	pos = *data;
	while (**data != '\0' && **data != ' ') (*data)++;
	if (**data == ' ') *(*data)++ = '\0';

	return pos;
}

void gslist_free_full (GSList *list, GDestroyNotify free_func) /* <=== gslist_free_full */ 
{
	GSList *tmp;

	if (list == NULL)
		return;

	for (tmp = list; tmp != NULL; tmp = tmp->next)
		free_func(tmp->data);

	g_slist_free(list);
}

static gboolean parse_cap_name(char *name, char **key, char **val) /* <=== parse_cap_name */ 
{
	const char *eq;

	g_return_val_if_fail(name != NULL, FALSE);
	g_return_val_if_fail(name[0] != '\0', FALSE);

	eq = strchr(name, '=');
	/* KEY only value */
	if (eq == NULL) {
		*key = g_strdup(name);
		*val = NULL;
	/* Some values are in a KEY=VALUE form, parse them */
	} else {
		*key = g_strndup(name, (gsize)(eq - name));
		*val = g_strdup(eq + 1);
	}

	return TRUE;
}

void irc_cap_finish_negotiation (IRC_SERVER_REC *server) /* <=== irc_cap_finish_negotiation */ 
{
	if (server->cap_complete)
		return;

	server->cap_complete = TRUE;
	irc_send_cmd_now(server, "CAP END");

	signal_emit("server cap end", 1, server);
}

static void signal_hooks_clean(Signal *rec) /* <=== signal_hooks_clean */ 
{
	SignalHook **hook, **next;
        int count;

        count = rec->remove_count;
        rec->remove_count = 0;

	for (hook = &rec->hooks; *hook != NULL; hook = next) {
		next = &(*hook)->next;

		if ((*hook)->func == NULL) {
                        next = hook;
			signal_remove_hook(rec, hook);

			if (--count == 0)
                                break;
		}
	}
}

void irc_server_send_data(IRC_SERVER_REC *server, const char *data, int len) /* <=== irc_server_send_data */ 
{
	if (net_sendbuffer_send(server->handle, data, len) == -1) {
		/* something bad happened */
		server->connection_lost = TRUE;
		return;
	}

	g_get_current_time(&server->last_cmd);

	/* A bit kludgy way to do the flood protection. In ircnet, there
	   actually is 1sec / 100 bytes penalty, but we rather want to deal
	   with the max. 1000 bytes input buffer problem. If we send more
	   than that with the burst, we'll get excess flooded. */
	if (len < 100 || server->cmd_queue_speed <= 10)
		server->wait_cmd.tv_sec = 0;
	else {
		memcpy(&server->wait_cmd, &server->last_cmd, sizeof(GTimeVal));
		g_time_val_add(&server->wait_cmd, (2 + len/100) * G_USEC_PER_SEC);
	}
}

static int signal_unref_full(Signal *rec, int remove) /* <=== signal_unref_full */ 
{
        g_assert(rec->refcount > 0);

	if (--rec->refcount != 0)
		return TRUE;

	/* remove whole signal from memory */
	if (rec->hooks != NULL) {
		g_error("signal_unref(%s) : BUG - hook list wasn't empty",
			signal_get_id_str(rec->id));
	}

	if (remove)
		g_hash_table_remove(signals, GINT_TO_POINTER(rec->id));
        g_free(rec);

	return FALSE;
}

static int signal_emit_real(Signal *rec, int params, va_list va, /* <=== signal_emit_real */ 
			    SignalHook *first_hook)
{
	const void *arglist[SIGNAL_MAX_ARGUMENTS];
	Signal *prev_emitted_signal;
        SignalHook *hook, *prev_emitted_hook;
	int i, stopped, stop_emit_count, continue_emit_count;

	for (i = 0; i < SIGNAL_MAX_ARGUMENTS; i++)
		arglist[i] = i >= params ? NULL : va_arg(va, const void *);

	/* signal_stop_by_name("signal"); signal_emit("signal", ...);
	   fails if we compare rec->stop_emit against 0. */
	stop_emit_count = rec->stop_emit;
	continue_emit_count = rec->continue_emit;

        signal_ref(rec);

	stopped = FALSE;
	rec->emitting++;

	prev_emitted_signal = current_emitted_signal;
	prev_emitted_hook = current_emitted_hook;
	current_emitted_signal = rec;

	for (hook = first_hook; hook != NULL; hook = hook->next) {
		if (hook->func == NULL)
			continue; /* removed */

		current_emitted_hook = hook;
#if SIGNAL_MAX_ARGUMENTS != 6
#  error SIGNAL_MAX_ARGUMENTS changed - update code
#endif
                signal_user_data = hook->user_data;
		hook->func(arglist[0], arglist[1], arglist[2], arglist[3],
			   arglist[4], arglist[5]);

		if (rec->continue_emit != continue_emit_count)
			rec->continue_emit--;

		if (rec->stop_emit != stop_emit_count) {
			stopped = TRUE;
			rec->stop_emit--;
			break;
		}
	}

	current_emitted_signal = prev_emitted_signal;
	current_emitted_hook = prev_emitted_hook;

	rec->emitting--;
	signal_user_data = NULL;

	if (!rec->emitting) {
		g_assert(rec->stop_emit == 0);
		g_assert(rec->continue_emit == 0);

                if (rec->remove_count > 0)
			signal_hooks_clean(rec);
	}

        signal_unref(rec);
	return stopped;
}

static void cap_emit_signal (IRC_SERVER_REC *server, char *cmd, char *args) /* <=== cap_emit_signal */ 
{
	char *signal_name;

	signal_name = g_strdup_printf("server cap %s %s", cmd, args? args: "");
	signal_emit(signal_name, 1, server);
	g_free(signal_name);
}

